def rule(i,qs,statement,loc,sids=(2,),limits='',status='documented',examples=()):
 rules.append(dict(id=f'calculix-R{i:02}',question_ids=list(qs),source_ids=[f'calculix-D{x:02}' for x in sids],statement=statement,locator=loc,examples=list(examples),limits=limits,status=status))
rule(1,['Q01'],'jobname.inp의 모델 정의 뒤 STEP/END STEP로 해석을 구성하며 dat/frd 등 출력 역할을 구분한다.',H+'node223.html; node352.html',limits='실행 명령과 결과는 이번에 재현하지 않았다.')
rule(2,['Q02'],'쉼표 구분·대소문자 비구분이며 고정 폭 입력으로 일반화하지 않는다. 요소가 15절점을 넘으면 행을 이어 최대16항목/행을 따른다.',H+'node223.html; node277.html',limits='문자 인코딩·모든 행의 길이/이어쓰기 예외 전수 검증 없음.',status='partial')
rule(3,['Q03'],'수치 단위의 일관성은 사용자가 유지하며 요소·재료·하중 값을 묵시적으로 SI로 변환하지 않는다.',H+'node4.html; node223.html',limits='원문 수식 그림의 모든 수치 단위표를 기계 schema로 변환하지 않았다.')
rule(4,['Q04'],'필수/선택·기본값·반복행은 카드별이다. SHELL SECTION의 COMPOSITE/MATERIAL·NODAL THICKNESS 조합은 같은 행 규칙이 아니다.',H+'node345.html; node274.html; node333.html',limits='143개 keyword의 모든 조건부 필드를 전수 schema화하지 않았다.',status='partial')
rule(5,['Q05'],'INCLUDE INPUT과 따옴표 파일명을 확인했다. 2.23 reader는 포함 깊이9 초과를 거부하고 경로를 fopen에 직접 전달한다.',H+'node303.html; src/readinput.c:171–186',(2,5),limits='상대 경로는 source fopen 동작에 근거한 process working-directory 해석이며 실제 플랫폼 실행 미확인.')
rule(6,['Q06'],'node/element set은 같은 이름을 쓸 수 있고 대소문자 비구분이다. set 재정의는 확장되며 참조 처리 순서는 reader가 조정한다.',H+'node223.html; node281.html; node328.html; node408.html',(2,5),limits='native 번호 전체 범위/중복 처리와 모든 keyword namespace 전수 대조 없음.',status='partial')
rule(7,['Q07'],'연결 순서와 면 번호는 요소형별이다. tetra 면·shell POS/NEG와 내부 확장 면 번호를 분리해 확인했다.',H+'node33.html Figure62; node277.html; node356.html',limits='Gmsh→CCX의 실제 permutation·orientation 테스트 미수행.')
rule(8,['Q08'],'요소 ELSET·MATERIAL 이름·SOLID/SHELL SECTION의 참조로 물성을 연결한다. 재료 블록의 뒤따르는 카드 문맥을 유지한다.',H+'node277.html; node311.html; node345.html; node346.html',limits='Abaqus PART/INSTANCE/ASSEMBLY 전체를 CalculiX가 동일 지원한다고 보지 않는다.')
rule(9,['Q09'],'BOUNDARY의 OP·AMPLITUDE와 시간 문맥을 구분한다. CONTACT PAIR는 surface/interaction 참조와 접촉형 혼합 제한을 갖는다.',H+'node227.html; node224.html; node249.html; node356.html',limits='모든 접촉 알고리즘·하중 조합의 수치 적합성은 검증하지 않았다.')
rule(10,['Q10'],'DYNAMIC의 EXPLICIT은 parameter 부재·값 생략이 다르다. restart READ는 선행, WRITE는 step 내부이며 rin/rout 역할이 다르다.',H+'node273.html; node338.html; node350.html',limits='process cancel/rollback과 입력 restart는 별개다.')
rule(11,['Q10'],'OUTPUT은 Abaqus 호환용 제한 카드다. FREQUENCY와 FREQUENCYF의 적용 대상·step간 유지 조건을 구분한다.',H+'node331.html',limits='Abaqus OUTPUT 하위 구조 전체 지원을 뜻하지 않는다.')
rule(12,['Q11'],'공식 2.23 test archive의 입력·참조 결과를 전수 파일 manifest로 확보하고 정상·contact·restart 예제를 골라 읽었다. 재실행은 하지 않았다.','test/beam10p.inp,.dat.ref; shell1.inp,.dat.ref; contact1.inp,.dat.ref; beamwrite/beamread pair',(6,),limits='공식 test archive의 개별 예제 재배포 조건은 별도 명확하지 않아 locator/해시만 배포. 오류 입력 또는 expected-failure 예제는 선정·검토하지 않았으며 전수 test 취득을 음성 시험 확보로 세지 않는다. beamperror는 error estimator 예제로, 의도적 실패 입력으로 분류하지 않는다.',status='partial',examples=('calculix-E01','calculix-E02','calculix-E03','calculix-E04'))
rule(13,['Q11'],'MIT solid/shell 템플릿은 CGX가 mesh/경계 파일을 먼저 생성한 뒤 CCX에 전달하는 예다. 단일 inp만으로 자립하지 않는다.','Elements/Solid,Elements/Shell; .fbd send; test.py reference values',(9,10),limits='cgx/ccx/Unix shell·NumPy/Matplotlib 환경을 이번에 실행하지 않았다.',status='partial',examples=('calculix-E05','calculix-E06'))
rule(14,['Q11'],'CGX write2aba는 요소별 mesh 출력과 제한된 dataset 제어를 구현한다. CCX readinput은 include/전처리 reader이고 새 모델 writer가 아니다.','CGX src/write2aba.c:26–249; CCX src/readinput.c:27–499',(5,7,8),limits='독립 빌드/전체 카드 생성 지원은 검증하지 않았다.',status='partial')
rule(15,['Q11','Q12'],'PrePoMax는 모델별 keyword tree와 user keyword를 출력한다. 소스 snapshot은 읽었으나 pin-byte 대조·LICENSE 확보가429로 막혔다.','CalculixFileWriter.cs:42–70,140–310,1452–1547',(11,12,13),limits='root LICENSE·선택 파일의 정확한 commit 대조 전 편입 자산으로 확정하지 않는다.',status='partial')
